# Print keys to understand structure
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print('  ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 1)
    elif isinstance(d, list) and len(d) < 20:
        for item in d[:3]:
            print_structure(item, indent + 1)

