import json
with open('/app/resources/treasury_bulletin_1944_01.json', 'r') as f:
    data = json.load(f)

# Let's look at the pages
pages = data['document']['pages']
for i, page in enumerate(pages):
    print(f'Page {i}: {page.get(\"page_number\", \"N/A\")}')
    if 'elements' in page:
        for elem in page['elements']:
            if 'table' in elem:
                print(f'  Table found')
                if 'rows' in elem['table']:
                    for row in elem['table']['rows'][:5]:
                        print(f'    Row: {row}')
